def below_zero(operations: List[int]) -> bool:
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

def max_product(num_str: str, N: int, K: int) -> int:
    def helper(start, k):
        if k == 0:
            return int(num_str[start:])
        max_val = 0
        for i in range(start + 1, N - k + 1):
            current_product = int(num_str[start:i]) * helper(i, k - 1)
            max_val = max(max_val, current_product)
        return max_val

    return helper(0, K)

