def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue
        term = ''
        if coeff < 0:
            term += '-'
        elif terms:  # Add '+' if not the first term and coeff is positive
            term += '+'
        if abs(coeff) != 1 or degree == 0:
            term += str(abs(coeff))
        if degree > 1:
            term += f'x^{degree}'
        elif degree == 1:
            term += 'x'
        terms.append(term)
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o

    if len(mapping) != len(set(original)):
        return "Failed"

    decoded_message = []
    for m in message:
        if m in mapping:
            decoded_message.append(mapping[m])
        else:
            return "Failed"

    return ''.join(decoded_message)

def count_partitions(n: int, k: int, x: int) -> int:
    def helper(n, k, x, memo):
        if n < k * x:
            return 0
        if k == 1:
            return 1 if n >= x else 0
        if (n, k, x) in memo:
            return memo[(n, k, x)]

        count = 0
        for i in range(x, n - k * x + x + 1):
            count += helper(n - i, k - 1, i, memo)

        memo[(n, k, x)] = count
        return count

    memo = {}
    return helper(n, k, x, memo)

