def count_sequences(n: int, last: int, memo: dict) -> int:
    if last in memo:
        return memo[last]
    if last == 1:
        return 1
    count = 0
    for i in range(1, last // 2 + 1):
        count += count_sequences(n, i, memo)
    memo[last] = count + 1  # +1 to include the sequence consisting of `last` itself
    return memo[last]

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    for person, person_statements in statements.items():
        for statement in person_statements:
            if statement in days_of_week:
                continue
            is_liar = person in liar_count
            if statement == f"I am guilty.":
                if is_liar and person == scenario:
                    return False
                if not is_liar and person != scenario:
                    return False
            elif statement == f"I am not guilty.":
                if is_liar and person != scenario:
                    return False
                if not is_liar and person == scenario:
                    return False
            elif statement.endswith(" is guilty."):
                accused = statement[:-8]
                if is_liar and accused == scenario:
                    return False
                if not is_liar and accused != scenario:
                    return False
            elif statement.endswith(" is not guilty."):
                accused = statement[:-11]
                if is_liar and accused != scenario:
                    return False
                if not is_liar and accused == scenario:
                    return False
    return True

def calculate_score(system: int, points: str) -> list:
    game_scores = []
    player_score = 0
    opponent_score = 0

    for point in points:
        if point == 'W':
            player_score += 1
        elif point == 'L':
            opponent_score += 1

        # Check if the game is finished
        if (player_score >= system or opponent_score >= system) and abs(player_score - opponent_score) >= 2:
            game_scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0

    # If there's an unfinished game, add its current score
    if player_score > 0 or opponent_score > 0:
        game_scores.append(f"{player_score}:{opponent_score}")

    return game_scores

def remaining_trees_after_clearing(l: int, areas: List[Tuple[int, int]]) -> int:
    cleared = set()
    for start, end in areas:
        cleared.update(range(start, end + 1))
    return l - len(cleared)

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            dp[i][j] = dp[i - 1][j]
            if j > 0:
                dp[i][j] = (dp[i][j] + dp[i][j - 1]) % MOD
            if j > a[i - 1]:
                dp[i][j] = (dp[i][j] - dp[i - 1][j - a[i - 1] - 1] + MOD) % MOD

    return dp[n][m]

def find_most_unhappy_day(schedule) -> int:
    max_unhappiness = 0
    most_unhappy_day = 0

    for day in range(7):
        total_hours = schedule[day][0] + schedule[day][1]
        unhappiness = total_hours - 8 if total_hours > 8 else 0

        if unhappiness > max_unhappiness:
            max_unhappiness = unhappiness
            most_unhappy_day = day + 1

    return most_unhappy_day

def jinjin_savings_plan(budgets: List[int]) -> int:
    pocket_money_per_month = 300
    savings = 0

    for month in range(12):
        remaining = pocket_money_per_month - budgets[month]
        if remaining < 0:
            return -(month + 1)
        savings += (remaining // 100) * 100

    savings_with_interest = savings * 1.20
    return int(savings_with_interest)

