def hanoi_double_iterative(n: int) -> int:
    if n == 0:
        return 0
    moves = 0
    current_moves = 2  # Base case for n=1
    for i in range(n):
        moves += current_moves
        current_moves = 3 * current_moves + 2  # Recursive relation
    return moves
